// Dashboard.jsx

import React, { useState, useEffect } from "react";
import { apiRequest, logout, setNavigateInstance } from "../services/auth";
import { useNavigate } from "react-router-dom";

const Dashboard = () => {
  const [activeSection, setActiveSection] = useState("accueil");
  const [selectedEntreprise, setSelectedEntreprise] = useState("");
  const [showModal, setShowModal] = useState(false);
  const [showAddEntrepriseModal, setShowAddEntrepriseModal] = useState(false);
  const [selectedDocument, setSelectedDocument] = useState(null);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [addEntrepriseData, setAddEntrepriseData] = useState({
    nom: "",
    siret: "",
    telephone: "",
    email: "",
    nomRepresentant: "",
    prenomRepresentant: "",
    domainesActivite: [],
    secteurActivite: "",
  });
  const [profileData, setProfileData] = useState({
    nom: "Logo service",
    siret: "12345678901234",
    adresse: "Ouagadougou 01 BP 824",
    email: "contact@techbat.fr",
    telephone: "0123456789",
    nomRepresentant: "Rayaissse ",
    prenomRepresentant: "Jude",
    secteurActivite: "Develloppement",
  });
  const [filters, setFilters] = useState({
    domaine: "",
    dateDebut: "",
    dateFin: "",
  });

  const entreprises = [
    { id: 1, nom: "SARL TechBat" },
    { id: 2, nom: "Construction Plus" },
    { id: 3, nom: "Eco Habitat" },
  ];

  const [publications, setPublications] = useState([]);
  const [loadingPublications, setLoadingPublications] = useState(true);
  const [errorPublications, setErrorPublications] = useState(null);

  const [apiDomainnesActivite, setApiDomainnesActivite] = useState([]);
  const [loadingDomaines, setLoadingDomainnes] = useState(true);
  const [errorDomaines, setErrorDomainnes] = useState(null);

  // Nouveaux états pour les appels d'offres
  const [appelsOffresCount, setAppelsOffresCount] = useState(0);
  const [loadingAppelsOffres, setLoadingAppelsOffres] = useState(true);
  const [errorAppelsOffres, setErrorAppelsOffres] = useState(null);

  // Nouveaux états pour les alertes
  const [alertesApi, setAlertesApi] = useState([]);
  const [loadingAlertes, setLoadingAlertes] = useState(true);
  const [errorAlertes, setErrorAlertes] = useState(null);

  // Nouveaux états pour les résultats
  const [resultatsApi, setResultatsApi] = useState([]);
  const [loadingResultats, setLoadingResultats] = useState(true);
  const [errorResultats, setErrorResultats] = useState(null);

  // Nouvel état pour la dernière date de revue importée
  const [lastReviewDate, setLastReviewDate] = useState("Non disponible");

  // Utilisez les domaines de l'API si disponibles, sinon un tableau vide
  const domainesActivite =
    apiDomainnesActivite.length > 0 ? apiDomainnesActivite : [];

  const secteursActivite = [
    "Bâtiment et Travaux Publics (BTP)",
    "Commerce général",
    "Transport et logistique",
    "Énergie et électricité",
    "Éducation et formation",
    "Agriculture et élevage",
  ];

  const handleAddEntrepriseDomaine = (domaineLibelle) => {
    const newDomaines = addEntrepriseData.domainesActivite.includes(
      domaineLibelle
    )
      ? addEntrepriseData.domainesActivite.filter((d) => d !== domaineLibelle)
      : [...addEntrepriseData.domainesActivite, domaineLibelle];

    setAddEntrepriseData({
      ...addEntrepriseData,
      domainesActivite: newDomaines,
    });
  };

  const handleSubmitAddEntreprise = (e) => {
    e.preventDefault();
    console.log("Nouvelle entreprise:", addEntrepriseData);
    setShowAddEntrepriseModal(false);
    setAddEntrepriseData({
      nom: "",
      siret: "",
      telephone: "",
      email: "",
      nomRepresentant: "",
      prenomRepresentant: "",
      domainesActivite: [],
      secteurActivite: "",
    });
  };

  const navigate = useNavigate();

  useEffect(() => {
    setNavigateInstance(navigate);
  }, [navigate]);

  useEffect(() => {
    const fetchPublications = async () => {
      setLoadingPublications(true);
      setErrorPublications(null);

      try {
        const response = await apiRequest(
          "http://127.0.0.1:8000/api/backend/api/publications/"
        );

        if (!response) {
          setErrorPublications(
            new Error("Votre session a expiré. Veuillez vous reconnecter.")
          );
          return;
        }

        if (!response.ok) {
          const errorData = await response.json();
          throw new Error(
            `Erreur HTTP lors de la récupération des publications: ${
              response.status
            } - ${JSON.stringify(errorData)}`
          );
        } else {
          const data = await response.json();
          const mappedData = data.map((pub) => ({
            id: pub.id,
            titre: pub.titre,
            date_publication: pub.date_publication,
            source: pub.source, // Gardé pour la logique interne et le modal si besoin
            type_publication: pub.type_publication,
            numero: pub.numero,
            domaine:
              pub.domaines.length > 0
                ? pub.domaines[0].libelle
                : "Non spécifié", // Gardé pour la logique de filtrage
            full_data: pub, // Garde toutes les données de l'API pour le modal
          }));
          setPublications(mappedData);

          // Calculer la dernière date de publication ici
          if (data.length > 0) {
            const latestDate = data.reduce((maxDate, pub) => {
              const pubDate = new Date(pub.date_publication);
              return pubDate > maxDate ? pubDate : maxDate;
            }, new Date(0)); // Initialize with a very early date

            setLastReviewDate(latestDate.toLocaleDateString("fr-FR")); // Format as desired
          } else {
            setLastReviewDate("Non disponible");
          }
        }
      } catch (error) {
        setErrorPublications(error);
        console.error(
          "Erreur lors de la récupération des publications:",
          error
        );
      } finally {
        setLoadingPublications(false);
      }
    };

    if (activeSection === "veille") {
      fetchPublications();
    }
  }, [activeSection, navigate]);

  useEffect(() => {
    const fetchDomainnes = async () => {
      setLoadingDomainnes(true);
      setErrorDomaines(null);
      try {
        const response = await apiRequest(
          "http://127.0.0.1:8000/api/entreprise/domaines/"
        );
        if (!response.ok) {
          throw new Error(`Erreur HTTP: ${response.status}`);
        }
        const data = await response.json();
        setApiDomainnesActivite(data);
      } catch (error) {
        console.error("Erreur lors de la récupération des domaines:", error);
        setErrorDomaines(error);
      } finally {
        setLoadingDomainnes(false);
      }
    };
    fetchDomainnes();
  }, []); // Exécuter une seule fois au montage du composant

  // Nouveau useEffect pour récupérer et compter les appels d'offres du mois
  useEffect(() => {
    const fetchAppelsOffresCount = async () => {
      setLoadingAppelsOffres(true);
      setErrorAppelsOffres(null);
      try {
        const response = await apiRequest(
          "http://127.0.0.1:8000/api/backend/api/appels-offres/"
        );
        if (!response) {
          setErrorAppelsOffres(
            new Error("Votre session a expiré. Veuillez vous reconnecter.")
          );
          setAppelsOffresCount(0); // Réinitialiser le compte en cas d'erreur de session
          return;
        }
        if (!response.ok) {
          const errorData = await response.json();
          throw new Error(
            `Erreur HTTP lors de la récupération des appels d'offres: ${
              response.status
            } - ${JSON.stringify(errorData)}`
          );
        }
        const data = await response.json();

        const currentMonth = new Date().getMonth();
        const currentYear = new Date().getFullYear();

        const count = data.filter((appel) => {
          // Assurez-vous que appel.publication.date_publication existe et est valide
          if (!appel.publication || !appel.publication.date_publication) {
            console.warn(
              "Appel d'offres sans date de publication valide:",
              appel
            );
            return false;
          }
          const pubDate = new Date(appel.publication.date_publication);
          return (
            pubDate.getMonth() === currentMonth &&
            pubDate.getFullYear() === currentYear
          );
        }).length;

        setAppelsOffresCount(count);
      } catch (error) {
        console.error(
          "Erreur lors de la récupération des appels d'offres:",
          error
        );
        setErrorAppelsOffres(error);
        setAppelsOffresCount(0); // Réinitialiser le compte en cas d'erreur
      } finally {
        setLoadingAppelsOffres(false);
      }
    };

    fetchAppelsOffresCount();
  }, []); // Dépendances vides pour n'exécuter qu'au montage du composant

  // Nouveau useEffect pour récupérer les alertes
  useEffect(() => {
    const fetchAlertes = async () => {
      setLoadingAlertes(true);
      setErrorAlertes(null);
      try {
        const response = await apiRequest(
          "http://127.0.0.1:8000/api/backend/api/alertes/"
        );
        if (!response) {
          setErrorAlertes(
            new Error("Votre session a expiré. Veuillez vous reconnecter.")
          );
          return;
        }
        if (!response.ok) {
          const errorData = await response.json();
          throw new Error(
            `Erreur HTTP lors de la récupération des alertes: ${
              response.status
            } - ${JSON.stringify(errorData)}`
          );
        }
        const data = await response.json();
        setAlertesApi(data);
      } catch (error) {
        console.error("Erreur lors de la récupération des alertes:", error);
        setErrorAlertes(error);
      } finally {
        setLoadingAlertes(false);
      }
    };

    if (activeSection === "alertes") {
      fetchAlertes();
    }
  }, [activeSection, navigate]);

  // Nouveau useEffect pour récupérer les résultats
  useEffect(() => {
    const fetchResultats = async () => {
      setLoadingResultats(true);
      setErrorResultats(null);
      try {
        const response = await apiRequest(
          "http://127.0.0.1:8000/api/backend/api/resultats/"
        );
        if (!response) {
          setErrorResultats(
            new Error("Votre session a expiré. Veuillez vous reconnecter.")
          );
          return;
        }
        if (!response.ok) {
          const errorData = await response.json();
          throw new Error(
            `Erreur HTTP lors de la récupération des résultats: ${
              response.status
            } - ${JSON.stringify(errorData)}`
          );
        }
        const data = await response.json();
        setResultatsApi(data);
      } catch (error) {
        console.error("Erreur lors de la récupération des résultats:", error);
        setErrorResultats(error);
      } finally {
        setLoadingResultats(false);
      }
    };

    if (activeSection === "alertes") {
      // Appeler quand la section alerte est active
      fetchResultats();
    }
  }, [activeSection, navigate]);

  const filteredPublications = publications.filter((pub) => {
    // Les filtres doivent correspondre aux champs mappés
    if (filters.domaine && pub.domaine !== filters.domaine) return false; // Le filtrage par domaine reste fonctionnel

    // Convertir les dates pour la comparaison si elles existent
    const pubDate = new Date(pub.date_publication);
    if (filters.dateDebut) {
      const debutDate = new Date(filters.dateDebut);
      if (pubDate < debutDate) return false;
    }
    if (filters.dateFin) {
      const finDate = new Date(filters.dateFin);
      if (pubDate > finDate) return false;
    }
    return true;
  });

  const renderSidebar = () => (
    <>
      <div
        className={`sidebar-overlay ${sidebarOpen ? "show" : ""}`}
        onClick={() => setSidebarOpen(false)}
      ></div>

      <div className={`sidebar ${sidebarOpen ? "show" : ""}`}>
        <div className="sidebar-header">
          <h4>VeilleMarches Pro</h4>
          <button
            className="btn-close-sidebar d-md-none"
            onClick={() => setSidebarOpen(false)}
          >
            <svg width="24" height="24" fill="currentColor" viewBox="0 0 16 16">
              <path d="M4.646 4.646a.5.5 0 0 1 .708 0L8 7.293l2.646-2.647a.5.5 0 0 1 .708.708L8.707 8l2.647 2.646a.5.5 0 0 1-.708.708L8 8.707l-2.646 2.647a.5.5 0 0 1-.708-.708L7.293 8 4.646 5.354a.5.5 0 0 1 0-.708z" />
            </svg>
          </button>
        </div>

        <div className="sidebar-content">
          <div className="mb-3">
            <select
              className="form-select sidebar-select"
              value={selectedEntreprise}
              onChange={(e) => setSelectedEntreprise(e.target.value)}
            >
              <option value="">Sélectionner une entreprise</option>
              {entreprises.map((ent) => (
                <option key={ent.id} value={ent.id}>
                  {ent.nom}
                </option>
              ))}
            </select>
          </div>

          <button
            className="btn btn-cta w-100 mb-4"
            onClick={() => setShowAddEntrepriseModal(true)}
          >
            <svg
              width="16"
              height="16"
              fill="currentColor"
              className="me-2"
              viewBox="0 0 16 16"
            >
              <path d="M8 4a.5.5 0 0 1 .5.5v3h3a.5.5 0 0 1 0 1h-3v3a.5.5 0 0 1-1 0v-3h-3a.5.5 0 0 1 0-1h3v-3A.5.5 0 0 1 8 4z" />
            </svg>
            Ajouter une entreprise
          </button>

          <nav className="sidebar-nav">
            <a
              href="#"
              className={`nav-link ${
                activeSection === "accueil" ? "active" : ""
              }`}
              onClick={() => {
                setActiveSection("accueil");
                setSidebarOpen(false);
              }}
            >
              <svg
                width="16"
                height="16"
                fill="currentColor"
                className="me-2"
                viewBox="0 0 16 16"
              >
                <path d="m8 3.293 6 6V13.5a1.5 1.5 0 0 1-1.5 1.5h-9A1.5 1.5 0 0 1 2 13.5V9.293l6-6zm5-.793V6l-2-2V2.5a.5.5 0 0 1 .5-.5h1a.5.5 0 0 1 .5.5z" />
                <path d="M7.293 1.5a1 1 0 0 1 1.414 0l6.647 6.646a.5.5 0 0 1-.708.708L8 2.207 1.354 8.854a.5.5 0 1 1-.708-.708L7.293 1.5z" />
              </svg>
              Accueil
            </a>
            <a
              href="#"
              className={`nav-link ${
                activeSection === "veille" ? "active" : ""
              }`}
              onClick={() => {
                setActiveSection("veille");
                setSidebarOpen(false);
              }}
            >
              <svg
                width="16"
                height="16"
                fill="currentColor"
                className="me-2"
                viewBox="0 0 16 16"
              >
                <path d="M14 4.5V14a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V2a2 2 0 0 1 2-2h5.5L14 4.5zM9.5 3A1.5 1.5 0 0 0 11 4.5h2V14a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1h5.5v2z" />
              </svg>
              Veille & Documents
            </a>
            <a
              href="#"
              className={`nav-link ${
                activeSection === "alertes" ? "active" : ""
              }`}
              onClick={() => {
                setActiveSection("alertes");
                setSidebarOpen(false);
              }}
            >
              <svg
                width="16"
                height="16"
                fill="currentColor"
                className="me-2"
                viewBox="0 0 16 16"
              >
                <path d="M8 16a2 2 0 0 0 2-2H6a2 2 0 0 0 2 2zM8 1.918l-.797.161A4.002 4.002 0 0 0 4 6c0 .628-.134 2.197-.459 3.742-.16.767-.376 1.566-.663 2.258h10.244c-.287-.692-.502-1.49-.663-2.258C12.134 8.197 12 6.628 12 6a4.002 4.002 0 0 0-3.203-3.92L8 1.917zM14.22 12c.223.447.481.801.78 1H1c.299-.199.557-.553.78-1C2.68 10.2 3 6.88 3 6c0-2.42 1.72-4.44 4.005-4.901a1 1 0 1 1 1.99 0A5.002 5.002 0 0 1 13 6c0 .88.32 4.2 1.22 6z" />
              </svg>
              Alertes & Résultats
            </a>
            <a
              href="#"
              className={`nav-link ${
                activeSection === "profil" ? "active" : ""
              }`}
              onClick={() => {
                setActiveSection("profil");
                setSidebarOpen(false);
              }}
            >
              <svg
                width="16"
                height="16"
                fill="currentColor"
                className="me-2"
                viewBox="0 0 16 16"
              >
                <path d="M8 8a3 3 0 1 0 0-6 3 3 0 0 0 0 6zm2-3a2 2 0 1 1-4 0 2 2 0 0 1 4 0zm4 8c0 1-1 1-1 1H3s-1 0-1-1 1-4 6-4 6 3 6 4zm-1-.004c-.001-.246-.154-.986-.832-1.664C11.516 10.68 10.289 10 8 10c-2.29 0-3.516.68-4.168 1.332-.678.678-.83 1.418-.832 1.664h10z" />
              </svg>
              Profil
            </a>
          </nav>
        </div>

        <div className="sidebar-footer">
          <button className="btn btn-outline-light w-100" onClick={logout}>
            <svg
              width="16"
              height="16"
              fill="currentColor"
              className="me-2"
              viewBox="0 0 16 16"
            >
              <path
                fillRule="evenodd"
                d="M10 12.5a.5.5 0 0 1-.5.5h-8a.5.5 0 0 1-.5-.5v-9a.5.5 0 0 1 .5-.5h8a.5.5 0 0 1 .5.5v2a.5.5 0 0 0 1 0v-2A1.5 1.5 0 0 0 9.5 2h-8A1.5 1.5 0 0 0 0 3.5v9A1.5 1.5 0 0 0 1.5 14h8a1.5 1.5 0 0 0 1.5-1.5v-2a.5.5 0 0 0-1 0v2z"
              />
              <path
                fillRule="evenodd"
                d="M15.854 8.354a.5.5 0 0 0 0-.708l-3-3a.5.5 0 0 0-.708.708L14.293 7.5H5.5a.5.5 0 0 0 0 1h8.793l-2.147 2.146a.5.5 0 0 0 .708.708l3-3z"
              />
            </svg>
            Déconnexion
          </button>
        </div>
      </div>
    </>
  );

  const renderMobileHeader = () => (
    <div className="mobile-header d-md-none">
      <button className="btn-menu" onClick={() => setSidebarOpen(true)}>
        <svg width="24" height="24" fill="currentColor" viewBox="0 0 16 16">
          <path
            fillRule="evenodd"
            d="M2.5 12a.5.5 0 0 1 .5-.5h10a.5.5 0 0 1 0 1H3a.5.5 0 0 1-.5-.5zm0-4a.5.5 0 0 1 .5-.5h10a.5.5 0 0 1 0 1H3a.5.5 0 0 1-.5-.5zm0-4a.5.5 0 0 1 .5-.5h10a.5.5 0 0 1 0 1H3a.5.5 0 0 1-.5-.5z"
          />
        </svg>
      </button>
      <h5 className="m-0">VeilleMarches Pro</h5>
    </div>
  );

  const renderAccueil = () => (
    <div className="main-content">
      <div className="content-header">
        <h2>Tableau de bord</h2>
        <p className="text-muted">Vue d'overview de votre activité de veille</p>
      </div>

      <div className="row mb-4">
        <div className="col-lg-4 col-md-6 mb-3">
          <div className="card kpi-card">
            <div className="card-body text-center">
              {loadingAppelsOffres ? (
                <p>Chargement...</p>
              ) : errorAppelsOffres ? (
                <p className="text-danger">Erreur de chargement</p>
              ) : (
                <h3 className="card-title">{appelsOffresCount}</h3>
              )}
              <p className="card-text">Appels d'offres ce mois</p>
            </div>
          </div>
        </div>
        <div className="col-lg-4 col-md-6 mb-3">
          <div className="card kpi-card">
            <div className="card-body text-center">
              {loadingAlertes ? (
                <p>Chargement...</p>
              ) : errorAlertes ? (
                <p className="text-danger">Erreur de chargement</p>
              ) : (
                <h3 className="card-title">{alertesApi.length}</h3>
              )}
              <p className="card-text">Alertes non lues</p>
            </div>
          </div>
        </div>
        <div className="col-lg-4 col-md-6 mb-3">
          <div className="card kpi-card">
            <div className="card-body text-center">
              <h3 className="card-title">{lastReviewDate}</h3>
              <p className="card-text">Date de la dernière revue importée</p>
            </div>
          </div>
        </div>
      </div>

      <div className="card">
        <div className="card-header">
          <h5 className="mb-0">Actions rapides</h5>
        </div>
        <div className="card-body">
          <div className="row">
            <div className="col-lg-4 col-md-6 mb-2">
              <button
                className="btn btn-cta w-100 "
                onClick={() => setActiveSection("veille")}
              >
                Rechercher manuellement
              </button>
            </div>
            <div className="col-lg-4 col-md-6 mb-2">
              <button
                className="btn btn-cta w-100"
                onClick={() => setActiveSection("profil")}
              >
                Modifier les paramètres du compte
              </button>
            </div>
            <div className="col-lg-4 col-md-6 mb-2">
              <button
                className="btn btn-cta w-100"
                onClick={() => setActiveSection("alertes")}
              >
                Voir dernières alertes
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );

  const renderVeille = () => (
    <div className="main-content">
      <div className="content-header">
        <h2>Veille & Documents</h2>
        <p className="text-muted">Consultation et gestion des publications</p>
      </div>

      {/* Filtres */}
      <div className="card mb-4">
        <div className="card-header">
          <h5 className="mb-0">Filtres</h5>
        </div>
        <div className="card-body">
          <div className="row">
            <div className="col-lg-4 col-md-6 mb-3">
              <label className="form-label">Domaine</label>
              {loadingDomaines ? (
                <p>Chargement des domaines...</p>
              ) : errorDomaines ? (
                <p className="text-danger">
                  Erreur de chargement des domaines.
                </p>
              ) : (
                <select
                  className="form-select"
                  value={filters.domaine}
                  onChange={(e) =>
                    setFilters({ ...filters, domaine: e.target.value })
                  }
                >
                  <option value="">Tous les domaines</option>
                  {domainesActivite.map((domaine) => (
                    <option key={domaine.id} value={domaine.libelle}>
                      {domaine.libelle}
                    </option>
                  ))}
                </select>
              )}
            </div>
            <div className="col-lg-4 col-md-6 mb-3">
              <label className="form-label">Date début</label>
              <input
                type="date"
                className="form-control"
                value={filters.dateDebut}
                onChange={(e) =>
                  setFilters({ ...filters, dateDebut: e.target.value })
                }
              />
            </div>
            <div className="col-lg-4 col-md-6 mb-3">
              <label className="form-label">Date fin</label>
              <input
                type="date"
                className="form-control"
                value={filters.dateFin}
                onChange={(e) =>
                  setFilters({ ...filters, dateFin: e.target.value })
                }
              />
            </div>
          </div>
        </div>
      </div>

      <div className="card mb-4">
        <div className="card-header">
          <h5 className="mb-0">Publications récentes</h5>
        </div>
        <div className="card-body">
          {loadingPublications ? (
            <p>Chargement des publications...</p>
          ) : errorPublications ? (
            <div className="alert alert-danger">
              Erreur lors du chargement des publications :{" "}
              {errorPublications.message}
              <br />
              Veuillez vérifier votre connexion ou vous reconnecter si l'erreur
              persiste.
            </div>
          ) : filteredPublications.length === 0 ? (
            <p>Aucune publication trouvée.</p>
          ) : (
            <div className="table-responsive">
              <table className="table table-hover">
                <thead>
                  <tr>
                    <th>Date de publication</th>
                    <th>Titre</th>
                    <th>Type de publication</th>
                    <th>Numéro</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {filteredPublications.map((pub) => (
                    <tr key={pub.id} style={{ cursor: "pointer" }}>
                      <td>
                        <div className="d-none d-md-block">
                          {pub.date_publication}
                        </div>
                        <div className="d-md-none small">
                          {pub.date_publication}
                        </div>
                      </td>
                      <td>
                        <div className="fw-bold">{pub.titre}</div>
                      </td>
                      <td>{pub.type_publication}</td>
                      <td>{pub.numero}</td>
                      <td>
                        <button
                          type="button"
                          className="btn btn-sm btn-outline-primary"
                          onClick={() => {
                            setSelectedDocument(pub.full_data); // Utilisez full_data pour le modal
                            setShowModal(true);
                          }}
                        >
                          Voir
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>

      <div className="card">
        <div className="card-header">
          <h5 className="mb-0">Bibliothèque de documents</h5>
        </div>
        <div className="card-body">
          <div className="mb-3">
            <input
              type="text"
              className="form-control"
              placeholder="Rechercher par mot-clé..."
            />
          </div>
          <div className="row">
            {[1, 2, 3, 4].map((i) => (
              <div key={i} className="col-lg-3 col-md-4 col-sm-6 mb-3">
                <div className="card document-card">
                  <div className="card-body text-center">
                    <svg
                      width="48"
                      height="48"
                      fill="currentColor"
                      className="text-danger mb-2"
                      viewBox="0 0 16 16"
                    >
                      <path d="M14 4.5V14a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V2a2 2 0 0 1 2-2h5.5L14 4.5zM9.5 3A1.5 1.5 0 0 0 11 4.5h2V14a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1h5.5v2z" />
                    </svg>
                    <h6 className="card-title">Document {i}</h6>
                    <small className="text-muted">PDF - 2.3 MB</small>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );

  const renderAlertes = () => (
    <div className="main-content">
      <div className="content-header">
        <h2>Alertes & Résultats</h2>
        <p className="text-muted">
          Suivi des notifications et résultats de candidatures
        </p>
      </div>

      <div className="row">
        <div className="col-lg-8 mb-4">
          <div className="card">
            <div className="card-header">
              <h5 className="mb-0">Alertes non traitées</h5>
            </div>
            <div className="card-body">
              {loadingAlertes ? (
                <p>Chargement des alertes...</p>
              ) : errorAlertes ? (
                <div className="alert alert-danger">
                  Erreur lors du chargement des alertes : {errorAlertes.message}
                </div>
              ) : alertesApi.length === 0 ? (
                <p>Aucune alerte trouvée.</p>
              ) : (
                alertesApi.map((alerte) => (
                  <div
                    key={alerte.id}
                    className="d-flex flex-column flex-sm-row justify-content-between align-items-start align-items-sm-center border-bottom py-2"
                  >
                    <div className="mb-2 mb-sm-0">
                      <h6 className="mb-1">
                        {alerte.type_alerte}: {alerte.contenu_alerte}
                      </h6>
                      <small className="text-muted">
                        {new Date(alerte.date_alerte).toLocaleDateString(
                          "fr-FR"
                        )}{" "}
                        - Canal: {alerte.canal_alerte}
                      </small>
                      {alerte.publication && (
                        <small className="text-muted d-block mt-1">
                          Publication: {alerte.publication.titre}
                        </small>
                      )}
                      {alerte.entreprise && (
                        <small className="text-muted d-block">
                          Entreprise: {alerte.entreprise.nom}
                        </small>
                      )}
                    </div>
                    <div className="d-flex">
                      <button className="btn btn-sm btn-outline-success me-2">
                        <svg
                          width="16"
                          height="16"
                          fill="currentColor"
                          viewBox="0 0 16 16"
                        >
                          <path d="M10.97 4.97a.75.75 0 0 1 1.07 1.05l-3.99 4.99a.75.75 0 0 1-1.08.02L4.324 8.384a.75.75 0 1 1 1.06-1.06l2.094 2.093 3.473-4.425a.267.267 0 0 1 .02-.022z" />
                        </svg>
                      </button>
                      <button className="btn btn-sm btn-outline-danger">
                        <svg
                          width="16"
                          height="16"
                          fill="currentColor"
                          viewBox="0 0 16 16"
                        >
                          <path d="M4.646 4.646a.5.5 0 0 1 .708 0L8 7.293l2.646-2.647a.5.5 0 0 1 .708.708L8.707 8l2.647 2.646a.5.5 0 0 1-.708.708L8 8.707l-2.646 2.647a.5.5 0 0 1-.708-.708L7.293 8 4.646 5.354a.5.5 0 0 1 0-.708z" />
                        </svg>
                      </button>
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>
        </div>

        <div className="col-lg-4">
          <div className="card">
            <div className="card-header">
              <h5 className="mb-0">Résultats récents</h5>
            </div>
            <div className="card-body">
              {loadingResultats ? (
                <p>Chargement des résultats...</p>
              ) : errorResultats ? (
                <div className="alert alert-danger">
                  Erreur lors du chargement des résultats :{" "}
                  {errorResultats.message}
                </div>
              ) : resultatsApi.length === 0 ? (
                <p>Aucun résultat trouvé.</p>
              ) : (
                resultatsApi.map((resultat) => (
                  <div key={resultat.marche.id} className="mb-3">
                    <div className="d-flex justify-content-between align-items-center mb-1">
                      <span className="fw-bold">
                        {resultat.marche.publication.titre}
                      </span>
                      <span
                        className={`badge ${
                          resultat.entreprise_attributaire &&
                          resultat.entreprise_attributaire.id ===
                            selectedEntreprise // Supposant que vous voulez vérifier si VOTRE entreprise est attributaire
                            ? "bg-success" // Si votre entreprise est l'attributaire
                            : "bg-danger" // Sinon (donc non retenu pour vous, ou un autre a été retenu)
                        }`}
                      >
                        {resultat.entreprise_attributaire &&
                        resultat.entreprise_attributaire.id ===
                          selectedEntreprise
                          ? "Retenu"
                          : "Non retenu"}
                      </span>
                    </div>
                    <small className="text-muted d-block">
                      Résultat publié le{" "}
                      {new Date(resultat.date_attribution).toLocaleDateString(
                        "fr-FR"
                      )}
                    </small>
                    <small className="text-muted d-block">
                      Attributaire:{" "}
                      {resultat.entreprise_attributaire
                        ? resultat.entreprise_attributaire.nom
                        : "N/A"}
                    </small>
                    <small className="text-muted d-block">
                      Montant attribué: {resultat.montant_attribue}
                    </small>
                    <a
                      href={resultat.marche.publication.source}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="small"
                    >
                      Voir l'annonce officielle
                    </a>
                  </div>
                ))
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );

  const renderProfil = () => (
    <div className="main-content">
      <div className="content-header">
        <h2>Profil</h2>
        <p className="text-muted">Gestion des informations de l'entreprise</p>
      </div>

      <div className="row">
        <div className="col-lg-8 mb-4">
          <div className="card mb-4">
            <div className="card-header">
              <h5 className="mb-0">Informations de l'entreprise</h5>
            </div>
            <div className="card-body">
              <form>
                <div className="row">
                  <div className="col-md-6 mb-3">
                    <label className="form-label">Nom de l'entreprise</label>
                    <input
                      type="text"
                      className="form-control"
                      value={profileData.nom}
                      onChange={(e) =>
                        setProfileData({ ...profileData, nom: e.target.value })
                      }
                    />
                  </div>
                  <div className="col-md-6 mb-3">
                    <label className="form-label">SIRET</label>
                    <input
                      type="text"
                      className="form-control"
                      value={profileData.siret}
                      onChange={(e) =>
                        setProfileData({
                          ...profileData,
                          siret: e.target.value,
                        })
                      }
                    />
                  </div>
                </div>
                <div className="row">
                  <div className="col-md-6 mb-3">
                    <label className="form-label">Nom du représentant</label>
                    <input
                      type="text"
                      className="form-control"
                      value={profileData.nomRepresentant}
                      onChange={(e) =>
                        setProfileData({
                          ...profileData,
                          nomRepresentant: e.target.value,
                        })
                      }
                    />
                  </div>
                  <div className="col-md-6 mb-3">
                    <label className="form-label">Prénom du représentant</label>
                    <input
                      type="text"
                      className="form-control"
                      value={profileData.prenomRepresentant}
                      onChange={(e) =>
                        setProfileData({
                          ...profileData,
                          prenomRepresentant: e.target.value,
                        })
                      }
                    />
                  </div>
                </div>
                <div className="mb-3">
                  <label className="form-label">Adresse</label>
                  <input
                    type="text"
                    className="form-control"
                    value={profileData.adresse}
                    onChange={(e) =>
                      setProfileData({
                        ...profileData,
                        adresse: e.target.value,
                      })
                    }
                  />
                </div>
                <div className="row">
                  <div className="col-md-6 mb-3">
                    <label className="form-label">Email</label>
                    <input
                      type="email"
                      className="form-control"
                      value={profileData.email}
                      onChange={(e) =>
                        setProfileData({
                          ...profileData,
                          email: e.target.value,
                        })
                      }
                    />
                  </div>
                  <div className="col-md-6 mb-3">
                    <label className="form-label">Téléphone</label>
                    <input
                      type="tel"
                      className="form-control"
                      value={profileData.telephone}
                      onChange={(e) =>
                        setProfileData({
                          ...profileData,
                          telephone: e.target.value,
                        })
                      }
                    />
                  </div>
                </div>
                <button type="submit" className="btn btn-cta">
                  Enregistrer les modifications
                </button>
              </form>
            </div>
          </div>

          <div className="card mb-4">
            <div className="card-header">
              <h5 className="mb-0">Secteur d'activité</h5>
            </div>
            <div className="card-body">
              <div className="row">
                {secteursActivite.map((secteur, index) => (
                  <div key={index} className="col-md-6 mb-2">
                    <div className="form-check">
                      <input
                        className="form-check-input"
                        type="checkbox"
                        name="secteurActivite"
                        id={`secteur-${index}`}
                        value={secteur}
                        checked={profileData.secteurActivite === secteur}
                        onChange={(e) =>
                          setProfileData({
                            ...profileData,
                            secteurActivite: e.target.value,
                          })
                        }
                      />
                      <label
                        className="form-check-label"
                        htmlFor={`secteur-${index}`}
                      >
                        {secteur}
                      </label>
                    </div>
                  </div>
                ))}
              </div>
              <div className="mt-3">
                <label className="form-label">Autre secteur</label>
                <input
                  type="text"
                  className="form-control"
                  placeholder="Précisez votre secteur d'activité..."
                />
              </div>
              <button className="btn btn-cta mt-3">
                Mettre à jour le secteur
              </button>
            </div>
          </div>

          <div className="card mb-4">
            <div className="card-header">
              <h5 className="mb-0">Domaines d'activité</h5>
            </div>
            <div className="card-body">
              {loadingDomaines ? (
                <p>Chargement des domaines...</p>
              ) : errorDomaines ? (
                <p className="text-danger">
                  Erreur de chargement des domaines.
                </p>
              ) : (
                <div className="row">
                  {domainesActivite.map((domaine) => (
                    <div key={domaine.id} className="col-md-6 mb-2">
                      <div className="form-check">
                        <input
                          className="form-check-input"
                          type="checkbox"
                          id={`domaine-${domaine.id}`}
                          // Logique pour cocher si le domaine est déjà sélectionné dans le profil
                          // Vous devrez probablement avoir un champ 'domainesActivite' dans profileData
                          // Par exemple: checked={profileData.domainesActivite.includes(domaine.libelle)}
                        />
                        <label
                          className="form-check-label"
                          htmlFor={`domaine-${domaine.id}`}
                        >
                          {domaine.libelle}
                        </label>
                      </div>
                    </div>
                  ))}
                </div>
              )}
              <div className="mt-3">
                <label className="form-label">Autre domaine</label>
                <input
                  type="text"
                  className="form-control"
                  placeholder="Précisez votre domaine d'activité..."
                />
              </div>
              <button className="btn btn-cta mt-3">
                Mettre à jour les domaines
              </button>
            </div>
          </div>
        </div>

        <div className="col-lg-4">
          <div className="card">
            <div className="card-header">
              <h5 className="mb-0">Changer le mot de passe</h5>
            </div>
            <div className="card-body">
              <form>
                <div className="mb-3">
                  <label className="form-label">Mot de passe actuel</label>
                  <input type="password" className="form-control" />
                </div>
                <div className="mb-3">
                  <label className="form-label">Nouveau mot de passe</label>
                  <input type="password" className="form-control" />
                </div>
                <div className="mb-3">
                  <label className="form-label">
                    Confirmer le nouveau mot de passe
                  </label>
                  <input type="password" className="form-control" />
                </div>
                <button type="submit" className="btn btn-cta w-100">
                  Mettre à jour le mot de passe
                </button>
              </form>
            </div>
          </div>
        </div>
      </div>
    </div>
  );

  const renderAddEntrepriseModal = () => (
    <div
      className={`modal fade ${showAddEntrepriseModal ? "show" : ""}`}
      style={{ display: showAddEntrepriseModal ? "block" : "none" }}
      tabIndex="-1"
    >
      <div className="modal-dialog modal-lg">
        <div className="modal-content">
          <div className="modal-header">
            <h5 className="modal-title">Ajouter une entreprise</h5>
            <button
              type="button"
              className="btn-close"
              onClick={() => setShowAddEntrepriseModal(false)}
            ></button>
          </div>
          <form onSubmit={handleSubmitAddEntreprise}>
            <div className="modal-body">
              <div className="row">
                <div className="col-md-6 mb-3">
                  <label className="form-label">Nom de l'entreprise *</label>
                  <input
                    type="text"
                    className="form-control"
                    value={addEntrepriseData.nom}
                    onChange={(e) =>
                      setAddEntrepriseData({
                        ...addEntrepriseData,
                        nom: e.target.value,
                      })
                    }
                    required
                  />
                </div>
                <div className="col-md-6 mb-3">
                  <label className="form-label">SIRET *</label>
                  <input
                    type="text"
                    className="form-control"
                    value={addEntrepriseData.siret}
                    onChange={(e) =>
                      setAddEntrepriseData({
                        ...addEntrepriseData,
                        siret: e.target.value,
                      })
                    }
                  />
                </div>
              </div>
              <div className="row">
                <div className="col-md-6 mb-3">
                  <label className="form-label">Téléphone</label>
                  <input
                    type="tel"
                    className="form-control"
                    value={addEntrepriseData.telephone}
                    onChange={(e) =>
                      setAddEntrepriseData({
                        ...addEntrepriseData,
                        telephone: e.target.value,
                      })
                    }
                  />
                </div>
                <div className="col-md-6 mb-3">
                  <label className="form-label">Email</label>
                  <input
                    type="email"
                    className="form-control"
                    value={addEntrepriseData.email}
                    onChange={(e) =>
                      setAddEntrepriseData({
                        ...addEntrepriseData,
                        email: e.target.value,
                      })
                    }
                  />
                </div>
              </div>
              <div className="row">
                <div className="col-md-6 mb-3">
                  <label className="form-label">Nom du représentant</label>
                  <input
                    type="text"
                    className="form-control"
                    value={addEntrepriseData.nomRepresentant}
                    onChange={(e) =>
                      setAddEntrepriseData({
                        ...addEntrepriseData,
                        nomRepresentant: e.target.value,
                      })
                    }
                  />
                </div>
                <div className="col-md-6 mb-3">
                  <label className="form-label">Prénom du représentant</label>
                  <input
                    type="text"
                    className="form-control"
                    value={addEntrepriseData.prenomRepresentant}
                    onChange={(e) =>
                      setAddEntrepriseData({
                        ...addEntrepriseData,
                        prenomRepresentant: e.target.value,
                      })
                    }
                  />
                </div>
              </div>

              <div className="mb-3">
                <label className="form-label">Secteur d'activité</label>
                <select
                  className="form-select"
                  value={addEntrepriseData.secteurActivite}
                  onChange={(e) =>
                    setAddEntrepriseData({
                      ...addEntrepriseData,
                      secteurActivite: e.target.value,
                    })
                  }
                >
                  <option value="">Sélectionner un secteur</option>
                  {secteursActivite.map((secteur, index) => (
                    <option key={index} value={secteur}>
                      {secteur}
                    </option>
                  ))}
                </select>
              </div>

              <div className="mb-3">
                <label className="form-label">Domaines d'activité</label>
                {loadingDomaines ? (
                  <p>Chargement des domaines...</p>
                ) : errorDomaines ? (
                  <p className="text-danger">
                    Erreur de chargement des domaines.
                  </p>
                ) : (
                  <div className="row">
                    {domainesActivite.map((domaine) => (
                      <div key={domaine.id} className="col-md-6 mb-2">
                        <div className="form-check">
                          <input
                            className="form-check-input"
                            type="checkbox"
                            id={`add-domaine-${domaine.id}`}
                            checked={addEntrepriseData.domainesActivite.includes(
                              domaine.libelle
                            )}
                            onChange={() =>
                              handleAddEntrepriseDomaine(domaine.libelle)
                            }
                          />
                          <label
                            className="form-check-label"
                            htmlFor={`add-domaine-${domaine.id}`}
                          >
                            {domaine.libelle}
                          </label>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </div>
            <div className="modal-footer">
              <button
                type="button"
                className="btn btn-secondary"
                onClick={() => setShowAddEntrepriseModal(false)}
              >
                Annuler
              </button>
              <button type="submit" className="btn btn-cta">
                Ajouter l'entreprise
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );

  const renderModal = () => (
    <div
      className={`modal fade ${showModal ? "show" : ""}`}
      style={{ display: showModal ? "block" : "none" }}
      tabIndex="-1"
    >
      <div className="modal-dialog modal-lg">
        <div className="modal-content">
          <div className="modal-header">
            <h5 className="modal-title">Aperçu du document</h5>
            <button
              type="button"
              className="btn-close"
              onClick={() => setShowModal(false)}
            ></button>
          </div>
          <div className="modal-body">
            {selectedDocument && (
              <div>
                <h6>{selectedDocument.titre}</h6>
                <p className="text-muted">
                  Date de publication : {selectedDocument.date_publication}
                </p>
                <p className="text-muted">Source : {selectedDocument.source}</p>
                <p className="text-muted">
                  Type : {selectedDocument.type_publication}
                </p>
                <p className="text-muted">Numéro : {selectedDocument.numero}</p>
                <p className="text-muted">
                  Domaines :{" "}
                  {selectedDocument.domaines.map((d) => d.libelle).join(", ")}
                </p>
                <div
                  className="bg-light p-4 text-center"
                  style={{ height: "400px" }}
                >
                  <svg
                    width="64"
                    height="64"
                    fill="currentColor"
                    className="text-muted mb-3"
                    viewBox="0 0 16 16"
                  >
                    <path d="M14 4.5V14a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V2a2 2 0 0 1 2-2h5.5L14 4.5zM9.5 3A1.5 1.5 0 0 0 11 4.5h2V14a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1h5.5v2z" />
                  </svg>
                  <p>Aperçu du document PDF</p>
                </div>
              </div>
            )}
          </div>
          <div className="modal-footer">
            <button
              type="button"
              className="btn btn-secondary"
              onClick={() => setShowModal(false)}
            >
              Fermer
            </button>
            {/* Modification ici pour le bouton Télécharger */}
            {selectedDocument && selectedDocument.source ? (
              <a
                href={selectedDocument.source}
                target="_blank"
                rel="noopener noreferrer"
                className="btn btn-cta"
              >
                Télécharger
              </a>
            ) : (
              <button type="button" className="btn btn-secondary" disabled>
                Télécharger (lien non disponible)
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );

  const renderContent = () => {
    switch (activeSection) {
      case "accueil":
        return renderAccueil();
      case "veille":
        return renderVeille();
      case "alertes":
        return renderAlertes();
      case "profil":
        return renderProfil();
      default:
        return renderAccueil();
    }
  };

  return (
    <>
      <div className="dashboard-container">
        {renderMobileHeader()}
        {renderSidebar()}
        <div className="main-wrapper">{renderContent()}</div>
        {showModal && renderModal()}
        {showAddEntrepriseModal && renderAddEntrepriseModal()}
      </div>
    </>
  );
};

export default Dashboard;
